r=run.read_text();survey=p/'provider-survey.py';assert sha(survey)=='b584d7e982c50dbd37d39d7e35eca3d63dda2a479b21c2f999831dbc0a372b9b' and "if local=='Sign16StrictFactor':" in r and "for rel,rec in survey['extra'].items():" in r and "'-M2800'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r
